//! End to end with the built binary on the synthetic samples (examples/sample, generated by
//! tests/make_samples.py): every item gets exactly the codes of expected_findings.json, media items are
//! analysed in worker processes, the audit log verifies (Rust verify-log and the independent
//! tests/verify_chain.py when RV_TEST_PYTHON is set), the reference comparison works, and a crash, hang or
//! memory blow-up in a worker becomes PARSER_FAILED without ending the run.

use assert_cmd::Command;
use serde_json::Value;
use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn only_dir(p: &Path) -> PathBuf {
    std::fs::read_dir(p)
        .unwrap()
        .flatten()
        .next()
        .expect("one run folder")
        .path()
}

fn audit(log_dir: &Path) -> Vec<Value> {
    std::fs::read_to_string(log_dir.join("audit.jsonl"))
        .unwrap()
        .lines()
        .map(|l| serde_json::from_str(l).unwrap())
        .collect()
}

fn analyze(args: &[&str], env: &[(&str, &str)]) -> (i32, tempfile::TempDir, String) {
    let out = tempfile::tempdir().unwrap();
    let mut c = Command::cargo_bin("rv-avauth").unwrap();
    c.env("RV_NO_TIMESTAMP", "1").arg("analyze");
    for a in args {
        c.arg(a);
    }
    for (k, v) in env {
        c.env(k, v);
    }
    let o = c
        .arg("--out")
        .arg(out.path())
        .arg("--progress")
        .arg("none")
        .output()
        .unwrap();
    (
        o.status.code().unwrap_or(-1),
        out,
        String::from_utf8_lossy(&o.stdout).into_owned() + &String::from_utf8_lossy(&o.stderr),
    )
}

#[test]
fn samples_match_expected_findings_and_the_log_verifies() {
    let ev = root().join("examples/sample/evidence");
    let (code, out, text) = analyze(
        &[
            "-i",
            ev.to_str().unwrap(),
            "--hash",
            "sha256,md5",
            "--lang",
            "all",
        ],
        &[],
    );
    assert_eq!(code, 0, "{text}");
    let report = only_dir(&out.path().join("reports"));
    let logs = only_dir(&out.path().join("logs"));
    let stats: Value =
        serde_json::from_str(&std::fs::read_to_string(report.join("statistics.json")).unwrap())
            .unwrap();
    let expected: BTreeMap<String, Vec<String>> = serde_json::from_str(
        &std::fs::read_to_string(root().join("examples/sample/expected_findings.json")).unwrap(),
    )
    .unwrap();
    let mut seen = BTreeSet::new();
    for it in stats["items"].as_array().unwrap() {
        let name = Path::new(it["path"].as_str().unwrap())
            .file_name()
            .unwrap()
            .to_string_lossy()
            .into_owned();
        let got: BTreeSet<String> = it["findings"]
            .as_array()
            .unwrap()
            .iter()
            .map(|c| c.as_str().unwrap().to_string())
            .collect();
        let want: BTreeSet<String> = expected[&name].iter().cloned().collect();
        assert_eq!(got, want, "{name}");
        seen.insert(name);
    }
    assert_eq!(seen.len(), expected.len());
    // Media items ran in worker processes; their outputs were hashed and audited.
    let entries = audit(&logs);
    let started = entries
        .iter()
        .filter(|e| {
            e["action"] == "analysis_started" && e["details"]["isolation"] == "worker_process"
        })
        .count();
    assert_eq!(started, expected.len(), "analysis_started for every item");
    let workers = entries
        .iter()
        .filter(|e| {
            e["action"] == "item_analyzed"
                && e["details"]["analysis"]["worker"]["status"] == "completed"
        })
        .count();
    assert_eq!(
        workers,
        expected.len() - 1,
        "every media candidate ran in a worker (not notes.txt)"
    );
    let analyzed: Vec<&Value> = entries
        .iter()
        .filter(|e| {
            e["action"] == "item_analyzed"
                && e["details"]["analysis"]["media_analysis"] == "completed"
        })
        .collect();
    assert_eq!(
        analyzed.len(),
        20,
        "every recognised media file is analysed"
    );
    assert!(
        analyzed
            .iter()
            .all(|e| e["details"]["analysis"]["evidence_rehash"]["match"] == true)
    );
    assert!(
        analyzed
            .iter()
            .all(|e| e["details"]["analysis"]["worker"]["status"] == "completed")
    );
    let structure = entries
        .iter()
        .filter(|e| e["action"] == "output_written" && e["details"]["kind"] == "structure")
        .count();
    assert_eq!(structure, 20);
    // The technical review carries the media section.
    let tech: Value = serde_json::from_str(
        &std::fs::read_to_string(report.join("items/00004-camera-original.mov/technical.json"))
            .unwrap(),
    )
    .unwrap();
    assert_eq!(tech["media"]["container"], "iso_bmff");
    assert_eq!(
        tech["media"]["media"]["streams"]["rows"][0]["codec"],
        "sowt"
    );
    assert!(
        tech["extracted_files"]
            .as_array()
            .unwrap()
            .iter()
            .any(|f| f["rel_path"] == "structure.json")
    );
    let html =
        std::fs::read_to_string(report.join("items/00004-camera-original.mov/technical.fr.html"))
            .unwrap();
    assert!(html.contains("Analyse multimédia") && html.contains("mvhd.creation"));
    // verify-log (Rust) re-hashes every recorded output.
    let v = Command::cargo_bin("rv-avauth")
        .unwrap()
        .arg("verify-log")
        .arg(&logs)
        .output()
        .unwrap();
    assert!(v.status.success(), "{}", String::from_utf8_lossy(&v.stdout));
    // The independent Python verifier, when a Python is configured.
    if let Some(py) = std::env::var_os("RV_TEST_PYTHON") {
        let o = std::process::Command::new(py)
            .arg(root().join("tests/verify_chain.py"))
            .arg(&logs)
            .output()
            .unwrap();
        let t = String::from_utf8_lossy(&o.stdout);
        assert!(o.status.success() && t.contains("chain: intact"), "{t}");
        let o = std::process::Command::new(std::env::var_os("RV_TEST_PYTHON").unwrap())
            .arg(root().join("tests/validate_reports.py"))
            .arg(&report)
            .output()
            .unwrap();
        assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stdout));
    }
}

#[test]
fn reference_comparison_end_to_end() {
    let ev = root().join("examples/sample/evidence");
    let reference = root().join("examples/sample/reference/camera-reference.mov");
    let (code, out, text) = analyze(
        &[
            "-i",
            ev.join("camera-original.mov").to_str().unwrap(),
            "-i",
            ev.join("voice-reencoded.m4a").to_str().unwrap(),
            "--reference",
            reference.to_str().unwrap(),
        ],
        &[],
    );
    assert_eq!(code, 0, "{text}");
    let report = only_dir(&out.path().join("reports"));
    let stats: Value =
        serde_json::from_str(&std::fs::read_to_string(report.join("statistics.json")).unwrap())
            .unwrap();
    let codes = |i: usize| -> Vec<String> {
        stats["items"][i]["findings"]
            .as_array()
            .unwrap()
            .iter()
            .map(|c| c.as_str().unwrap().to_string())
            .collect()
    };
    assert!(codes(0).contains(&"REFERENCE_CONSISTENT".to_string()));
    assert!(codes(1).contains(&"REFERENCE_DIFFERS".to_string()));
    let logs = only_dir(&out.path().join("logs"));
    let refs: Vec<Value> = audit(&logs)
        .into_iter()
        .filter(|e| e["action"] == "item_analyzed")
        .map(|e| e["details"]["analysis"]["references"][0].clone())
        .collect();
    assert!(
        refs.iter()
            .all(|r| r["sha256"].as_str().is_some_and(|h| h.len() == 64))
    );
    let (code, _, text) = analyze(
        &["-i", ev.to_str().unwrap(), "--reference", "missing.mov"],
        &[],
    );
    assert_eq!(code, 1, "{text}");
    assert!(text.contains("reference file not found"));
}

fn fault_run(fault: &str, extra: &[&str]) -> (i32, Vec<Value>) {
    let ev = root().join("examples/sample/evidence/tone-original.wav");
    let notes = root().join("examples/sample/evidence/notes.txt");
    let mut args = vec!["-i", ev.to_str().unwrap(), "-i", notes.to_str().unwrap()];
    args.extend_from_slice(extra);
    let (code, out, text) = analyze(&args, &[("RV_WORKER_TEST_FAULT", fault)]);
    assert!(text.contains("DONE"), "{text}");
    (code, audit(&only_dir(&out.path().join("logs"))))
}

fn parser_failed_reason(entries: &[Value]) -> String {
    let e = entries
        .iter()
        .find(|e| {
            e["action"] == "item_analyzed"
                && e["item"]
                    .as_str()
                    .is_some_and(|p| p.ends_with("tone-original.wav"))
        })
        .unwrap();
    let f = e["details"]["findings"]
        .as_array()
        .unwrap()
        .iter()
        .find(|f| f["code"] == "PARSER_FAILED")
        .expect("PARSER_FAILED");
    f["params"]["reason"].as_str().unwrap().to_string()
}

#[test]
#[cfg(debug_assertions)]
fn worker_crash_hang_and_memory_blow_up_become_parser_failed() {
    let (code, entries) = fault_run("crash", &[]);
    assert_eq!(code, 3);
    assert_eq!(parser_failed_reason(&entries), "crashed");
    // The partial file the crashed worker left is hashed and audited.
    assert!(
        entries
            .iter()
            .any(|e| e["action"] == "output_written" && e["details"]["kind"] == "partial_output")
    );
    // The text file next to it was analysed normally, and the run finished.
    assert!(entries.iter().any(|e| e["action"] == "run_finished"));
    let (code, entries) = fault_run("hang", &["--worker-timeout", "2"]);
    assert_eq!(code, 3);
    assert_eq!(parser_failed_reason(&entries), "timeout");
    let (code, entries) = fault_run("oom", &["--worker-memory", "256"]);
    assert_eq!(code, 3);
    let r = parser_failed_reason(&entries);
    assert!(r == "memory_limit" || r == "crashed", "{r}");
}
